@router.post("/shares/documents/{doc_id}")
def create_document_share_link(
    doc_id: str,
    user: User = Security(get_scoped_user, scopes=["shares:create"]),
    db: Session = Depends(get_db)
):
    doc = db.query(Document).filter(Document.id == doc_id, Document.owner_id == user.id).first()
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")

    share_token = secrets.token_urlsafe(32)
    share = DocumentShare(doc_id=doc_id, token=share_token, created_by=user.id)
    db.add(share)
    db.commit()
    return {"share_url": f"https://api.example.com/public/shares/{share_token}"}
